Tool response:
Tool: search_wireless_headphones
Description: Search for wireless noise-cancelling headphones with specific filters.

Find products matching the search term, filtered by minimum average rating, 
over minimum reviews, and active inventory at the specified store with the given condition.
Results are ordered by review count descending and limited to top N.
Parameters:
    {
      "type": "object",
      "properties": {
        "search_term": {
          "type": "string",
          "description": "Search term for product name",
          "title": "Search Term"
        },
        "min_rating": {
          "type": "number",
          "description": "Minimum average rating (default: 4.7)",
          "default": 4.7,
          "title": "Min Rating"
        },
        "min_reviews": {
          "type": "integer",
          "description": "Minimum number of reviews (default: 500)",
          "default": 500,
          "title": "Min Reviews"
        },
        "store_id": {
          "type": "integer",
          "description": "Store ID to check availability (e.g., 242 for Chicago, IL)",
          "title": "Store Id"
        },
        "condition": {
          "type": "string",
          "description": "Inventory condition type (default: 'Open-Box')",
          "default": "Open-Box",
          "title": "Condition"
        },
        "limit": {
          "type": "integer",
          "description": "Maximum number of results to return (default: 3)",
          "default": 3,
          "title": "Limit"
        }
      },
      "required": [
        "search_term",
        "store_id"
      ]
    }
